import {Collection,decodeFile,lexicalSearch,rankSemantic} from './core.mjs';
const $=id=>document.getElementById(id);const shelf=new Collection();let worker=null,serial=0,pending=new Map(),generation=0,index=null,busy=false;
const status=message=>{$('status').textContent=message;};
function setBusy(value){busy=value;$('cancel').disabled=!value;$('progress').hidden=!value;$('search-form').querySelector('button').disabled=value;$('model').disabled=value;for(const id of ['query','mode','files','demo'])$(id).disabled=value;}
function cancel(){generation++;worker?.terminate();worker=null;for(const p of pending.values())p.reject(Error('Cancelled.'));pending.clear();index=null;setBusy(false);status('Stopped. Your files remain on the shelf; lexical search is available.');}
function retireWorker(failed,message){
 if(worker!==failed)return;
 failed.terminate();worker=null;index=null;
 for(const p of pending.values())p.reject(Error(message));pending.clear();
}
function embed(texts){
 if(!worker){
  const current=new Worker('./embedding-worker.mjs',{type:'module'});worker=current;
  current.onmessage=({data})=>{
   if(worker!==current)return;
   const p=pending.get(data.id);if(!p)return;
   if(data.error){retireWorker(current,data.error);return;}
   pending.delete(data.id);p.resolve(data.vectors);
  };
  current.onerror=()=>retireWorker(current,'Model worker failed. Try again or use lexical search.');
 }
 return new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});try{worker.postMessage({id,texts});}catch{retireWorker(worker,'Model request failed. Try loading the model again.');}});
}
function changed(){generation++;index=null;setBusy(false);$('results').replaceChildren();$('source').close();$('source-text').replaceChildren();renderLibrary();}
function renderLibrary(){$('count').textContent=String(shelf.files.length);$('library').replaceChildren();for(const file of shelf.files){const row=document.createElement('div');row.className='file-row';const name=document.createElement('span');name.textContent=file.name;const meta=document.createElement('small');meta.textContent=`${file.id} · ${file.chunks.length} passages`;const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.setAttribute('aria-label',`Remove ${file.name} (${file.id})`);remove.onclick=()=>{if(busy)cancel();shelf.remove(file.id);changed();status('File removed. Search results cleared.');};row.append(name,meta,remove);$('library').append(row);}}
async function importFiles(files){if(busy)cancel();const ticket=++generation;setBusy(true);status('Reading selected files locally…');let added=0,errors=[];for(const f of files){try{if(f.size>512000)throw Error('File exceeds 500 KB.');const bytes=new Uint8Array(await f.arrayBuffer());if(ticket!==generation)return;shelf.add(f.name,decodeFile(f.name,bytes));added++;}catch(e){if(ticket!==generation)return;errors.push(`${f.name}: ${e.message}`);}}if(ticket!==generation)return;changed();status(`${added} file${added===1?'':'s'} added.${errors.length?' '+errors.join(' '):' Ready for lexical search or local semantic search.'}`);$('files').value='';}
$('files').onchange=e=>importFiles([...e.target.files]);$('cancel').onclick=cancel;
$('clear').onclick=()=>{cancel();shelf.clear();changed();$('source').close();$('source-text').textContent='';$('query').value='';status('Shelf cleared. No documents are saved by LazyShelf.');};
$('demo').onclick=()=>{if(busy)cancel();shelf.clear();for(const [name,text] of [['Library.md','Borrowed novels can be returned through the slot beside the main entrance, even after the library closes. Renewals are unavailable when another reader has reserved the book.'],['Equipment.txt','Adapter DVC-0179 must use the amber cable. Do not attach the blue cable. Adapter DVC-0719 uses the blue cable.'],['Photos.md','Keep a second copy of family pictures on a separate external drive. Compare file hashes after copying. Disconnect the spare disk between updates.']])shelf.add(name,text);changed();$('query').value='Where can I leave a borrowed book after closing?';status('Three fictional sample files loaded. Try semantic search or enter an exact word for lexical search.');};
$('model').onclick=async()=>{if(busy)return;const ticket=generation;setBusy(true);status('Preparing the local model… first use may take a moment.');try{await embed([]);if(ticket===generation)status('Local model ready. Select semantic search to find related passages.');}catch(e){if(ticket===generation)status(e.message);}finally{if(ticket===generation)setBusy(false);}};
function showSource(chunk){const file=shelf.files.find(f=>f.id===chunk.fileId);if(!file)return;$('source-title').textContent=`${file.name} · ${file.id} · line ${chunk.line}`;const pre=$('source-text');pre.replaceChildren(document.createTextNode(file.text.slice(0,chunk.start)));const mark=document.createElement('mark');mark.textContent=file.text.slice(chunk.start,chunk.end);pre.append(mark,document.createTextNode(file.text.slice(chunk.end)));$('source').showModal();requestAnimationFrame(()=>mark.scrollIntoView({block:'center'}));}
$('source-close').onclick=()=>$('source').close();
function queryChanged(){if(busy)cancel();$('results').replaceChildren();status('Search changed. Run Find passages for the current query and mode.');}
$('query').oninput=queryChanged;$('mode').onchange=queryChanged;
function renderResults(rows,mode){$('results').replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='empty';p.textContent='No matching words. Try a different phrase or use semantic search.';$('results').append(p);return;}for(const [i,c]of rows.slice(0,12).entries()){const file=shelf.files.find(f=>f.id===c.fileId);const card=document.createElement('article');card.className='result-card';const label=document.createElement('p');label.className='result-meta';label.textContent=`${String(i+1).padStart(2,'0')} / ${file.name} · ${file.id} · line ${c.line}`;const body=document.createElement('p');body.className='excerpt';body.textContent=c.text;const foot=document.createElement('div');foot.className='result-footer';const score=document.createElement('span');score.textContent=mode==='semantic'?`Similarity ${c.score.toFixed(3)} · not confidence`:`Lexical score ${c.score.toFixed(2)}`;const open=document.createElement('button');open.textContent='View exact source';open.onclick=()=>showSource(c);foot.append(score,open);card.append(label,body,foot);$('results').append(card);}}
$('search-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const q=$('query').value.trim();if(!q){status('Enter a search phrase.');$('query').focus();return;}if(q.length>500){status('Keep queries under 500 characters.');return;}if(!shelf.files.length){status('Add TXT or Markdown files, or try the fictional sample shelf.');return;}const mode=$('mode').value,ticket=generation;const chunks=shelf.chunks;setBusy(true);status(mode==='semantic'?'Finding related passages on your device…':'Matching words…');try{let rows;if(mode==='semantic'){if(!index){const vectors=[];for(let i=0;i<chunks.length;i+=16){vectors.push(...await embed(chunks.slice(i,i+16).map(c=>c.text)));if(ticket!==generation)return;status(`Indexing ${Math.min(i+16,chunks.length)} of ${chunks.length} passages…`);}index={revision:shelf.revision,vectors};}const [query]=await embed([q]);if(ticket!==generation)return;rows=rankSemantic(chunks,index.vectors,query);}else rows=lexicalSearch(chunks,q);if(ticket!==generation)return;renderResults(rows,mode);status(`${Math.min(12,rows.length)} passages shown. ${mode==='semantic'?'Relatedness is not proof of an answer. Check the source, especially identifiers and negation.':'Exact token matching; word forms and paraphrases may differ.'}`);}catch(e){if(ticket===generation)status(e.message);}finally{if(ticket===generation)setBusy(false);}};
setBusy(false);renderLibrary();
